const LD_dot=(x,y,col)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="9" fill="${col}"/>`;
/* the book's numbers, computed once */
const LD_AM=Math.log(1/(0.32*0.32))/(2*0.03);                    // 37.98 cm^-1
const LD_GG=10+LD_AM;                                            // 47.98 cm^-1 modal gain
const LD_PW=(I,Ith=20,s=0.30)=>Math.max(0,s*(I-Ith));            // mW from mA above threshold
/* a Gaussian mode across a layer: centre cx, base y0, width px per sigma, height h; returns the path points */
const LD_mode=(cx,y0,sg,h,from=-3,to=3)=>{let p=[];for(let i=0;i<=60;i++){const z=from+(to-from)*i/60;p.push([cx+z*sg,y0-h*Math.exp(-z*z/2)])}return p};
const LD_pts=p=>p.map(q=>q[0].toFixed(1)+','+q[1].toFixed(1)).join(' ');
/* half-width (in sigma) of a centred layer holding a fraction G of a Gaussian mode: sqrt(2)·erfinv(G) */
const LD_half=G=>{let lo=0,hi=5;const erf=x=>{const t=1/(1+.3275911*x);return 1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-x*x)};for(let i=0;i<60;i++){const m=(lo+hi)/2;if(erf(m/Math.SQRT2)<G)lo=m;else hi=m}return lo};
/* a mode over a gain layer holding fraction G (the shaded part is the overlap) */
const LD_overlap=(cx,y0,sg,h,G,col,lab)=>{const a=LD_half(G),full=LD_mode(cx,y0,sg,h),ins=LD_mode(cx,y0,sg,h,-a,a);
 return `<rect x="${(cx-a*sg).toFixed(1)}" y="${y0-h-16}" width="${(2*a*sg).toFixed(1)}" height="${h+16}" fill="${LD_GAIN}" stroke="${ORG}" stroke-width="2"/>`+
 `<polygon points="${(cx-a*sg).toFixed(1)},${y0} ${LD_pts(ins)} ${(cx+a*sg).toFixed(1)},${y0}" fill="${col}" fill-opacity=".35"/>`+
 `<polyline points="${LD_pts(full)}" fill="none" stroke="${col}" stroke-width="4"/>`+LD_L(cx-3.2*sg,y0,cx+3.2*sg,y0,'#ADB5BD',3)+(lab?LD_T(cx,y0+30,lab,{fs:22,fw:800,a:'middle',fill:col}):'')};
/* a small L-I plot: x0,y0 origin, kx px per mA, ky px per mW; Ith in mA; Imax in mA */
const LD_axes=(x0,y0,w,h,xl,yl)=>LD_L(x0,y0,x0+w,y0,'#ADB5BD',3)+LD_L(x0,y0,x0,y0-h,'#ADB5BD',3)+LD_T(x0+w,y0+30,xl,{fs:22,a:'end',fill:LD_GREY})+LD_T(x0+8,y0-h+4,yl,{fs:22,fill:LD_GREY});
/* two energy levels with dots: n2 dots on the upper line, n1 on the lower */
const LD_levels=(x,y,w,n2,n1)=>{let s=LD_L(x,y,x+w,y,INK,4)+LD_L(x,y+70,x+w,y+70,INK,4)+LD_T(x-10,y+8,'E₂',{fs:22,fw:800,a:'end'})+LD_T(x-10,y+78,'E₁',{fs:22,fw:800,a:'end'});
 for(let i=0;i<n2;i++)s+=LD_dot(x+24+i*(w-48)/Math.max(1,5),y-12,ORG);for(let i=0;i<n1;i++)s+=LD_dot(x+24+i*(w-48)/Math.max(1,5),y+58,BLU);return s};
/* a cavity: two mirrors at x0 and x1, gain block between, centre line yc */
const LD_cav=(x0,x1,yc,hh)=>`<rect x="${x0+8}" y="${yc-hh}" width="${x1-x0-16}" height="${2*hh}" rx="6" fill="${LD_GAIN}" stroke="${ORG}" stroke-width="2"/>`+`<rect x="${x0}" y="${yc-hh-14}" width="8" height="${2*hh+28}" fill="${LD_MIRROR}"/><rect x="${x1-8}" y="${yc-hh-14}" width="8" height="${2*hh+28}" fill="${LD_MIRROR}"/>`;

